def stop(self):
    if self.srv is None:
        return
    if self.srv.poll() is None:

spec = any(a.startswith("--spec-type") for a in self.extra)
# per-phase finish_reason counts so capped (length) outputs are
# visible rather than silently distorting tok/s
for ph in ("single-agent", "single-mem", "dual-agent", "dual-mem"):
    rows = [r for r in self.rows if r.get("phase") == ph]
    if rows:
        by = {}
        for r in rows:
            fr = r.get("finish_reason") or "missing"
            by[fr] = by.get(fr, 0) + 1
        self.note(f"finish_reason {ph}: " +
                  " ".join(f"{k}={v}" for k, v in sorted(by.items())))
fgs = [r for r in self.rows if r["fg_bg"] == "fg"]

